// Rows come back only on the first check or for hotels whose nightly price dropped.
const rows = $input.all().map((i) => i.json).filter((h) => typeof h.pricePerNight === 'number');
if (!rows.length) return [];
const first = rows.every((h) => h.change === 'first_check');
const lines = rows.slice(0, 15).map((h) => `• ${h.name} (${h.rating ?? '–'}★): ${h.currency || ''} ${h.pricePerNight}/night${h.previousPricePerNight != null ? ` (was ${h.previousPricePerNight})` : ''}${h.googleHotelsUrl ? ` <${h.googleHotelsUrl}|view>` : ''}`);
return [{ json: { message: `${first ? '🏨 Hotel prices now tracked' : '🔻 Hotel price drops'} for ${rows[0].search}:\n${lines.join('\n')}` } }];
